        )
    samples = self.score_samples(X)
    try:
        result = math.fsum(samples) / len(X)
    except (
        OverflowError,
        ValueError,
        ZeroDivisionError,
    ) as exc:
        raise FloatingPointError(
            "non-finite value encountered while scoring"
        ) from exc
    if not math.isfinite(result):
        raise FloatingPointError(
            "non-finite value encountered while scoring"
        )
    if result == 0.0:
        result = 0.0
    return result
